export const getIntlCityBySlug = (slug: string) => INTERNATIONAL_CITIES.find((c) => c.slug === slug);
export const getIntlCountries = () => Array.from(new Set(INTERNATIONAL_CITIES.map((c) => c.countrySlug))).sort();
export const getIntlCitiesByCountry = (countrySlug: string) => INTERNATIONAL_CITIES.filter((c) => c.countrySlug === countrySlug);
